parameters.jsCode:
const qualityOutput = $input.first().json.choices[0].message.content;
const parts = qualityOutput.split('|');

let scores = {};
let passed = false;
let suggestion = '';
let totalScore = 0;

parts.forEach(part => {
  const [key, value] = part.split(':');
  if (key && value) {
    const trimKey = key.trim();
    const trimVal = value.trim();
    scores[trimKey] = trimVal;
    if (trimKey === '总分') totalScore = parseFloat(trimVal) || 0;
    if (trimKey === '判定') passed = trimVal === 'PASS';
    if (trimKey === '建议') suggestion = trimVal;
  }
});

const threshold = $('工作流配置（填入你的API Key）').first().json.qualityThreshold || 7;
passed = totalScore >= threshold;

console.log('AI质检结果:', JSON.stringify(scores));
console.log('是否通过:', passed, '总分:', totalScore, '阈值:', threshold);

return [{
  json: {
    quality_scores: scores,
    total_score: totalScore,
    passed: passed,
    suggestion: suggestion,
    threshold: threshold,
    raw_output: qualityOutput
  }
}];

